package com.careerpilot.backend.modules.application.services;
import com.careerpilot.backend.modules.resume.domain.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ResumeSelectionEngine { public record Candidate(Resume resume,ResumeVersion version,double matchScore,Set<String> technologies,String specialization){} public record Selection(UUID resumeId,int version,double score){} public Selection select(List<Candidate> candidates,Set<String> jobTechnologies,String jobCategory){return candidates.stream().max(Comparator.comparingDouble(c->score(c,jobTechnologies,jobCategory))).map(c->new Selection(c.resume().getId(),c.version().getVersionNumber(),score(c,jobTechnologies,jobCategory))).orElseThrow(()->new IllegalStateException("No existing resume version available"));}private double score(Candidate c,Set<String> tech,String category){double s=c.matchScore();if(c.technologies()!=null&&tech!=null)s+=c.technologies().stream().filter(tech::contains).count()*2;if(category!=null&&category.equalsIgnoreCase(c.specialization()))s+=10;s+=c.version().getVersionNumber()*0.01;return s;} }
